ervation"]}],"constraint":[{"key":"ele-1","severity":"error","human":"All FHIR elements must have a @value or children","expression":"hasValue() or (children().count() > id.count())","xpath":"@value|f:*|h:div","source":"http://hl7.org/fhir/StructureDefinition/Element"}],"isModifier":false,"isSummary":false}]},"differential":{"element":[{"id":"Goal","path":"Goal","definition":"\\\\-","comment":"\\\\-","mustSupport":false,"mapping":[{"identity":"argonaut-dq-dstu2","map":"Goal"}]},{"id":"Goal.lifecycleStatus","extension":[{"url":"http://hl7.org/fhir/us/core/StructureDefinition/uscdi-requirement","valueBoolean":true}],"path":"Goal.lifecycleStatus","short":"(USCDI) proposed | planned | accepted | active | on-hold | completed | cancelled | entered-in-error | rejected","mustSupport":true,"binding":{"strength":"required","valueSet":"http://hl7.org/fhir/ValueSet/goal-status"},"mapping":[{"identity":"argonaut-dq-dstu2","map":"Goal.status"}]},{"id":"Goal.description","extension":[{"url":"http://hl7.org/fhir/us/core/StructureDefinition/uscdi-requirement","valueBoolean":true}],"path":"Goal.description","short":"(USCDI) Code or text describing goal","mustSupport":true,"binding":{"strength":"extensible","description":"Value set to describe the Goal","valueSet":"http://hl7.org/fhir/us/core/ValueSet/us-core-goal-description"},"mapping":[{"identity":"argonaut-dq-dstu2","map":"Goal.description"}]},{"id":"Goal.subject","extension":[{"url":"http://hl7.org/fhir/us/core/StructureDefinition/uscdi-requirement","valueBoolean":true}],"path":"Goal.subject","short":"(USCDI) Who this goal is intended for","type":[{"code":"Reference","targetProfile":["http://hl7.org/fhir/us/core/StructureDefinition/us-core-patient"]}],"mustSupport":true,"mapping":[{"identity":"argonaut-dq-dstu2","map":"Goal.subject"}]},{"id":"Goal.start[x]","extension":[{"url":"http://hl7.org/fhir/us/core/StructureDefinition/uscdi-requirement","valueBoolean":true}],"path":"Goal.start[x]","short":"(USCDI) When goal pursuit begins"