nguages"},{"url":"http://hl7.org/fhir/StructureDefinition/elementdefinition-bindingName","valueString":"Language"},{"url":"http://hl7.org/fhir/StructureDefinition/elementdefinition-isCommonBinding","valueBoolean":true}],"strength":"preferred","description":"A human language.","valueSet":"http://hl7.org/fhir/ValueSet/languages"},"mapping":[{"identity":"v2","map":"PID-15, NK1-20, LAN-2"},{"identity":"rim","map":"./languageCommunication"},{"identity":"servd","map":"./Languages.LanguageSpokenCode"}]}]},"differential":{"element":[{"id":"Practitioner","path":"Practitioner","definition":"\\\\-","comment":"\\\\-","alias":["Provider"],"mustSupport":false},{"id":"Practitioner.identifier","path":"Practitioner.identifier","slicing":{"discriminator":[{"type":"pattern","path":"$this"}],"rules":"open"},"comment":"NPI must be supported as the identifier system in the US, Tax id is allowed, Local id is allowed in addition to another identifier supplied by a jurisdictional authority such as a practitioner's *Drug Enforcement Administration (DEA)* number.","min":1,"mustSupport":true},{"id":"Practitioner.identifier.system","path":"Practitioner.identifier.system","min":1,"max":"1","type":[{"code":"uri"}],"mustSupport":true},{"id":"Practitioner.identifier.value","path":"Practitioner.identifier.value","min":1,"max":"1","type":[{"code":"string"}],"mustSupport":true},{"id":"Practitioner.identifier:NPI","path":"Practitioner.identifier","sliceName":"NPI","patternIdentifier":{"system":"http://hl7.org/fhir/sid/us-npi"},"condition":["us-core-16","us-core-17"],"constraint":[{"key":"us-core-16","severity":"error","human":"NPI must be 10 digits","expression":"value.matches('^[0-9]{10}$')","xpath":"f:value/f:matches(value,/^[0-9]{10}$/)"},{"key":"us-core-17","severity":"error","human":"NPI check digit must be valid (Luhn algorithm check)","expression":"(((select(value.substring(0,1).toInteger()).select(iif($this<5, $this*2, (($this*2)-9))))+(value.substring(1,1).toInteger())+(select(value.substring(2,1).toInteger()).select(iif($this<5, $this*2, (($this*2)-9))))+(value.substring(3,1).toInteger())+(select(value.substring(4,1).toInteger()).select(iif($this<5, $this*2, (($this*2)-9))))+(value.substring(5,1).toInteger())+(select(value.substring(6,1).toInteger()).select(iif($this<5, $this*2, (($this*2)-9))))+(value.substring(7,1).toInteger())+(select(value.substring(8,1).toInteger()).select(iif($this<5, $this*2, (($this*2)-9))))+(value.substring(9,1).toInteger()) + 24)mod 10=0)"}],"mustSupport":true},{"id":"Practitioner.name","path":"Practitioner.name","min":1,"mustSupport":true},{"id":"Practitioner.name.family","path":"Practitioner.name.family","min":1,"max":"1","type":[{"code":"string"}],"mustSupport":true},{"id":"Practitioner.telecom","path":"Practitioner.telecom","mustSupport":true},{"id":"Practitioner.telecom.system","path":"Practitioner.telecom.system","mustSupport":true},{"id":"Practitioner.telecom.value","path":"Practitioner.telecom.value","mustSupport":true},{"id":"Practitioner.address","path":"Practitioner.address","short":"Address(es) of the practitioner","definition":"Address(es) of the practitioner","requirements":"\\\\-","mustSupport":true},{"id":"Practitioner.address.line","path":"Practitioner.address.line","max":"4","type":[{"code":"string"}],"mustSupport":true},{"id":"Practitioner.address.city","path":"Practitioner.address.city","max":"1","type":[{"code":"string"}],"mustSupport":true},{"id":"Practitioner.address.state","path":"Practitioner.address.state","max":"1","type":[{"code":"string"}],"mustSupport":true,"binding":{"strength":"extensible","description":"Two letter USPS alphabetic codes.","valueSet":"http://hl7.org/fhir/us/core/ValueSet/us-core-usps-state"},"mapping":[{"identity":"servd","map":"./Sites"}]},{"id":"Practitioner.address.postalCode","path":"Practitioner.address.postalCode","short":"US Zip Codes","max":"1","type":[{"code":"string"}],"mustSupport":true},{"id":"Practitioner.address.country","path":"Practitioner.address.country","max":"